declare target_question_id uuid; target_snapshot text[];
begin
  if (select count(*) from public.learning_skill_definitions where skill_code in ('read-clock-time','interpret-clock-hands','use-five-minute-intervals','distinguish-am-pm','calculate-time-after','calculate-time-before','calculate-elapsed-time','correct-time-reasoning'))<>8 then raise exception 'grade2 time skill definitions are incomplete'; end if;
  if not exists(select 1 from public.learning_content_versions version join public.learning_units unit on unit.id=version.unit_id where version.id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid and version.status='published' and unit.unit_code='grade2-time' and unit.sort_order=11) then raise exception 'grade2 time published identity is missing'; end if;
  if (select count(*) from public.learning_stages where content_version_id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid)<>4 or (select count(*) from public.learning_questions q join public.learning_stages s on s.id=q.stage_id where s.content_version_id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid)<>40 or (select count(*) from public.learning_question_options o join public.learning_questions q on q.id=o.question_id join public.learning_stages s on s.id=q.stage_id where s.content_version_id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid)<>160 then raise exception 'grade2 time 4/40/160 structure failed'; end if;
  if (select count(*) from public.learning_question_skills m join public.learning_questions q on q.id=m.question_id join public.learning_stages s on s.id=q.stage_id where s.content_version_id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid and m.is_primary)<>40 then raise exception 'grade2 time mapping coverage failed'; end if;
  select q.id,array_agg(m.skill_code order by m.is_primary desc,m.skill_code) into target_question_id,target_snapshot from public.learning_questions q join public.learning_stages s on s.id=q.stage_id join public.learning_question_skills m on m.question_id=q.id where s.content_version_id='81f5083b-44b5-4344-8457-9522dbe74c97'::uuid group by q.id,s.display_order,q.display_order order by s.display_order,q.display_order limit 1;
  if pg_typeof(target_snapshot)<>'text[]'::regtype or cardinality(target_snapshot)<>1 then raise exception 'grade2 time snapshot compatibility failed'; end if;
  begin update public.learning_question_skills set is_primary=false where question_id=target_question_id; raise exception 'published grade2 time mapping update was accepted'; exception when object_not_in_prerequisite_state then null; end;
  begin delete from public.learning_question_skills where question_id=target_question_id; raise exception 'published grade2 time mapping delete was accepted'; exception when object_not_in_prerequisite_state then null; end;
  if (select count(*) from public.learning_content_versions where id in ('51000000-0000-4000-8000-000000000003','61000000-0000-4000-8000-000000000003','376377cb-4093-4f29-bc92-5ca42b27a726','8a600f52-61e6-4d6c-b6d0-b1f524b42df6','d6d3caf7-1375-4dde-9fea-c44b5776cc04','29ac4fe6-847f-4c01-a402-ffce3440fad7','bf3dd0af-3cff-4d29-bdd3-f12e2ef08d9d','8eb41f37-e2f1-42e9-a1c8-657ca08c9302','06abbe3b-4061-4afe-84ca-d69122f9d7b8') and status='published')<>9 then raise exception 'existing published identities changed'; end if;
  if exists(select 1 from public.learning_attempts) or exists(select 1 from public.learning_attempt_answers) or exists(select 1 from public.learning_stage_progress) or exists(select 1 from public.learning_stage_first_passes) or exists(select 1 from public.sticker_transactions) or exists(select 1 from public.learning_mistake_review_answers) then raise exception 'content rollout changed official or review data'; end if;
  if has_table_privilege('anon','public.learning_question_skills','SELECT,INSERT,UPDATE,DELETE') or has_table_privilege('authenticated','public.learning_question_skills','SELECT,INSERT,UPDATE,DELETE') or has_table_privilege('service_role','public.learning_question_skills','INSERT,UPDATE,DELETE') then raise exception 'grade2 time mapping ACL failed'; end if;
end
$fixture$;
select 'grade2 time content fixture passed' result;
